module github.com/gotests-reimpl/gotests

go 1.21
EOF
cat > internal/models/models.go <<'EOF'
// Package models defines the data structures that are passed to the test
// templates.
package models

import (
	"strings"
	"unicode"
)

// Expression describes a Go type expression.
type Expression struct {
	Value      string
	IsStar     bool
	IsVariadic bool
	IsWriter   bool
	Underlying string
}

// String returns the type as it should be declared in the test.
func (e *Expression) String() string {
	value := e.Value
	if e.IsStar {
		value = "*" + value
	}
	if e.IsVariadic {
		return "[]" + value
	}
	return value
}

// Field is a parameter, result, or struct field.
type Field struct {
	Name  string
	Type  *Expression
	Index int
}

// IsWriter reports whether the field is an io.Writer.
func (f *Field) IsWriter() bool {
	return f.Type.IsWriter
}

// IsStruct reports whether the field's underlying type is a struct.
func (f *Field) IsStruct() bool {
	return strings.HasPrefix(f.Type.Underlying, "struct")
}

// IsBasicType reports whether the field is a basic (comparable) type.
func (f *Field) IsBasicType() bool {
	return isBasicType(f.Type.String()) || isBasicType(f.Type.Underlying)
}

func isBasicType(t string) bool {
	switch t {
	case "bool", "string", "int", "int8", "int16", "int32", "int64", "uint",
		"uint8", "uint16", "uint32", "uint64", "uintptr", "byte", "rune",
		"float32", "float64", "complex64", "complex128":
		return true
	default:
		return false
	}
}

// IsNamed reports whether the field has a usable name.
func (f *Field) IsNamed() bool {
	return f.Name != "" && f.Name != "_"
}

// ShortName returns the lowercased first letter of the field's type.
func (f *Field) ShortName() string {
	return strings.ToLower(string([]rune(f.Type.Value)[0]))
}

// Receiver is a method receiver.
type Receiver struct {
	*Field
	Fields []*Field
}

// TypeParam is a type parameter of a generic function or type.
type TypeParam struct {
	Name       string
	Constraint string
}

// Function describes a function or method under test.
type Function struct {
	Name         string
	IsExported   bool
	Receiver     *Receiver
	Parameters   []*Field
	Results      []*Field
	ReturnsError bool
	TypeParams   []*TypeParam
	Body         string
}

// TestParameters returns the parameters that become test arguments.
func (f *Function) TestParameters() []*Field {
	var ps []*Field
	for _, p := range f.Parameters {
		if p.IsWriter() {
			continue
		}
		ps = append(ps, p)
	}
	return ps
}

// TestResults returns the results that are compared in the test.
func (f *Function) TestResults() []*Field {
	var ps []*Field
