func recursiveFiles(root, orig string) ([]models.Path, error) {
	if orig != "..." {
		root = strings.TrimSuffix(orig, "/...")
	}
	if root == "" {
		root = "."
	}
	root, err := filepath.Abs(root)
	if err != nil {
		return nil, fmt.Errorf("filepath.Abs: %v\n", err)
	}
