{"command":"cd /workspace/internal/render && cat > render.go <<'EOF'
// Package render renders tests from templates.
package render

import (
	"embed"
	"fmt"
	"io"
	"io/fs"
	"os"
	"path"
	"reflect"
	"strings"
	"text/template"

	"github.com/gotests-reimpl/gotests/internal/models"
)

//go:embed templates/default/*.tmpl
var defaultFS embed.FS

//go:embed templates/testify/*.tmpl
var namedFS embed.FS

// namedTemplates contains the named template sets selectable with -template.
var namedTemplates fs.FS

func init() {
	sub, err := fs.Sub(namedFS, "templates")
	if err != nil {
		panic(err)
	}
	namedTemplates = sub
}

// Render renders tests.
type Render struct {
	tmpls *template.Template
}

// New returns a Render with the default templates loaded.
func New() *Render {
	r := &Render{
		tmpls: template.New("render").Funcs(map[string]interface{}{
			"Field":        fieldName,
			"Receiver":     receiverName,
			"Param":        parameterName,
			"Want":         wantName,
			"Got":          gotName,
			"TypeArgs":     typeArgs,
			"FieldType":    fieldType,
			"ReceiverType": receiverType,
		}),
	}
	sub, err := fs.Sub(defaultFS, "templates/default")
	if err != nil {
		panic(err)
	}
	r.tmpls = template.Must(r.tmpls.ParseFS(sub, "*.tmpl"))
	return r
}

// LoadCustomTemplates loads all the templates in a directory.
func (r *Render) LoadCustomTemplates(dir string) error {
	files, err := os.ReadDir(dir)
	if err != nil {
		return fmt.Errorf("ioutil.ReadDir: %v", err)
	}

	templateFiles := []string{}
	for _, f := range files {
		templateFiles = append(templateFiles, path.Join(dir, f.Name()))
	}
	tmpls, err := r.tmpls.ParseFiles(templateFiles...)
	if err != nil {
		return fmt.Errorf("tmpls.ParseFiles: %v", err)
	}
	r.tmpls = tmpls
	return nil
}

// LoadCustomTemplatesName loads a named, built-in template set.
func (r *Render) LoadCustomTemplatesName(name string) error {
	sub, err := fs.Sub(namedTemplates, name)
	if err != nil {
		return fmt.Errorf("templates.Sub: %v", err)
	}
	tmpls, err := r.tmpls.ParseFS(sub, "*.tmpl")
	if err != nil {
