{"command":"cd /workspace/internal/imports && cat > imports.go <<'EOF'
// Package imports implements the subset of goimports used to clean up the
// generated test files: it removes unused imports, adds missing standard
// library imports, sorts and groups the import declarations, and formats
// the code.
package imports

import (
	"bufio"
	"bytes"
	"fmt"
	"go/ast"
	"go/format"
	"go/parser"
	"go/printer"
	"go/token"
	"io"
	"path"
	"regexp"
	"sort"
	"strconv"
	"strings"
	"unicode"
	"unicode/utf8"
)

// Process formats and adjusts imports for the provided file.
func Process(filename string, src []byte) ([]byte, error) {
	fset := token.NewFileSet()
	file, err := parser.ParseFile(fset, filename, src, parser.ParseComments)
	if err != nil {
		return nil, err
	}
	fixImports(fset, file)
	return formatFile(fset, file)
}

// references maps package names to the set of exported selectors used.
type references map[string]map[string]bool

type importInfo struct {
	name string // explicit name, may be empty
	path string
}

func (i importInfo) ident() string {
	if i.name != "" {
		return i.name
	}
	return importPathToAssumedName(i.path)
}

type fixType int

const (
	addImport fixType = iota
	deleteImport
)

type importFix struct {
	info      importInfo
	identName string
	fixType   fixType
}

func collectReferences(f *ast.File) references {
	refs := references{}
	ast.Inspect(f, func(node ast.Node) bool {
		v, ok := node.(*ast.SelectorExpr)
		if !ok {
			return true
		}
		xident, ok := v.X.(*ast.Ident)
		if !ok {
			return true
		}
		if xident.Obj != nil {
			// If the parser can resolve it, it's not a package ref.
			return true
		}
		if !ast.IsExported(v.Sel.Name) {
			// Whatever this is, it's not exported from a package.
			return true
		}
		pkgName := xident.Name
		r := refs[pkgName]
		if r == nil {
			r = make(map[string]bool)
			refs[pkgName] = r
		}
		r[v.Sel.Name] = true
		return true
	})
	return refs
}

func collectImports(f *ast.File) []importInfo {
	var imports []importInfo
	for _, imp := range f.Imports {
		var name string
		if imp.Name != nil {
			name = imp.Name.Name
		}
		if imp.Path.Value == `"C"` || name == "_" || name == "." {
			continue
		}
		p := strings.Trim(imp.Path.Value, `"`)
		imports = append(imports, importInfo{name: name, path: p})
	}
	return imports
}

func fixImports(fset *token.FileSet, f *ast.File) {
	refs := collectReferences(f)
	existing := map[string][]importInfo{}
	for _, imp := range collectImports(f) {
		existing[imp.ident()] = append(existing[imp.ident()], imp)
	}

	missing := references{}
	for left, rights := range refs {
		if _, ok := existing[left]; !ok {
			missing[left] = rights
		}
	}

	var selected []importInfo
	for left, rights := range missing {
		if imp, ok := findStdlibImport(left, rights); ok {
			selected = append(selected, imp)
		}
	}

	var fixes []*importFix
	for _, imps := range existing {
		for _, imp := range imps {
			if _, ok := refs[imp.ident()]; !ok {
				fixes = append(fixes, &importFix{info: imp, identName: imp.ident(), fixType: deleteImport})
			}
		}
	}
	sortFixes(fixes)
	var selectedFixes []*importFix
	for _, imp := range selected {
		selectedFixes = append(selectedFixes, &importFix{info: imp, identName: imp.ident(), fixType: addImport})
	}
	sortFixes(selectedFixes)
	fixes = append(fixes, selectedFixes...)

	for _, fix := range fixes {
		switch fix.fixType {
		case deleteImport:
			deleteNamedImport(fset, f, fix.info.name, fix.info.path)
		case addImport:
			addNamedImport(fset, f, fix.info.name, fix.info.path)
		}
	}
}

func sortFixes(fixes []*importFix) {
	sort.Slice(fixes, func(i, j int) bool {
		fi, fj := fixes[i], fixes[j]
		if fi.info.path != fj.info.path {
			return fi.info.path < fj.info.path
		}
		if fi.info.name != fj.info.name {
			return fi.info.name < fj.info.name
		}
		if fi.identName != fj.identName {
			return fi.identName < fj.identName
		}
		return fi.fixType < fj.fixType
	})
}

var stdlibIndex map[string]map[string]bool
var stdlibByBase map[string][]string

func loadStdlib() {
	if stdlibIndex != nil {
		return
	}
	stdlibIndex = make(map[string]map[string]bool, len(stdlibSymbols))
	stdlibByBase = make(map[string][]string)
	for p, syms := range stdlibSymbols {
		m := make(map[string]bool)
		for _, s := range strings.Fields(syms) {
			m[s] = true
		}
		stdlibIndex[p] = m
	}
	var paths []string
	for p := range stdlibIndex {
		paths = append(paths, p)
	}
	sort.Strings(paths)
	for _, p := range paths {
		b := path.Base(p)
		stdlibByBase[b] = append(stdlibByBase[b], p)
	}
}

func localBase(nm string) string {
	ans := path.Base(nm)
	if ans[0] == 'v' {
		// this is called, for instance, with math/rand/v2 and returns rand/v2
		if _, err := strconv.Atoi(ans[1:]); err == nil {
			ix := strings.LastIndex(nm, ans)
			more := path.Base(nm[:ix])
			ans = path.Join(more, ans)
		}
	}
	return ans
}

func findStdlibImport(name string, syms map[string]bool) (importInfo, bool) {
	loadStdlib()
	var candidates []string
	if name == "rand" {
		candidates = []string{"crypto/rand", "math/rand/v2", "math/rand"}
	} else {
		candidates = stdlibByBase[name]
	}
	for _, c := range candidates {
		if localBase(c) != name && importPathToAssumedName(c) != name {
			continue
		}
		exports := stdlibIndex[c]
		allFound := true
		for s := range syms {
			if !exports[s] {
				allFound = false
				break
			}
		}
		if allFound {
			return importInfo{path: c}, true
		}
	}
	return importInfo{}, false
}

// importPathToAssumedName returns the assumed package name of an import path.
func importPathToAssumedName(importPath string) string {
	base := path.Base(importPath)
	if strings.HasPrefix(base, "v") {
		if _, err := strconv.Atoi(base[1:]); err == nil {
			dir := path.Dir(importPath)
			if dir != "." {
				base = path.Base(dir)
			}
		}
	}
	base = strings.TrimPrefix(base, "go-")
	if i := strings.IndexFunc(base, notIdentifier); i >= 0 {
		base = base[:i]
	}
	return base
}

func notIdentifier(ch rune) bool {
	return !('a' <= ch && ch <= 'z' || 'A' <= ch && ch <= 'Z' ||
		'0' <= ch && ch <= '9' ||
		ch == '_' ||
		ch >= utf8.RuneSelf && (unicode.IsLetter(ch) || unicode.IsDigit(ch)))
}

func formatFile(fset *token.FileSet, file *ast.File) ([]byte, error) {
	mergeImports(file)
	sortImports(fset.File(file.Pos()), file)
	var spacesBefore []string // import paths we need spaces before
	for _, impSection := range astImports(fset, file) {
		// Within each block of contiguous imports, see if any
		// import lines are in different group numbers. If so,
		// we'll need to put a space between them so it's
		// compatible with gofmt.
		lastGroup := -1
		for _, importSpec := range impSection {
			importPath, _ := strconv.Unquote(importSpec.Path.Value)
			groupNum := importGroup(importPath)
			if groupNum != lastGroup && lastGroup != -1 {
				spacesBefore = append(spacesBefore, importPath)
			}
			lastGroup = groupNum
		}
	}

	printConfig := &printer.Config{Mode: printer.UseSpaces | printer.TabIndent, Tabwidth: 8}

	var buf bytes.Buffer
	err := printConfig.Fprint(&buf, fset, file)
	if err != nil {
		return nil, err
	}
	out := buf.Bytes()
	if len(spacesBefore) > 0 {
		out, err = addImportSpaces(bytes.NewReader(out), spacesBefore)
		if err != nil {
			return nil, err
		}
		out, err = format.Source(out)
		if err != nil {
			return nil, err
		}
	}
	return out, nil
}

func importGroup(importPath string) int {
	if strings.HasPrefix(importPath, "appengine") {
		return 2
	}
	firstComponent := strings.Split(importPath, "/")[0]
	if strings.Contains(firstComponent, ".") {
		return 1
	}
	return 0
}

var impLine = regexp.MustCompile(`^\s+(?:[\w\.]+\s+)?"(.+?)"`)

func addImportSpaces(r io.Reader, breaks []string) ([]byte, error) {
	var out bytes.Buffer
	in := bufio.NewReader(r)
	inImports := false
	done := false
	for {
		s, err := in.ReadString('\n')
		if err == io.EOF {
			break
		} else if err != nil {
			return nil, err
		}

		if !inImports && !done && strings.HasPrefix(s, "import") {
			inImports = true
		}
		if inImports && (strings.HasPrefix(s, "var") ||
			strings.HasPrefix(s, "func") ||
			strings.HasPrefix(s, "const") ||
			strings.HasPrefix(s, "type")) {
			done = true
			inImports = false
		}
		if inImports && len(breaks) > 0 {
			if m := impLine.FindStringSubmatch(s); m != nil {
				if m[1] == breaks[0] {
					out.WriteByte('\n')
					breaks = breaks[1:]
				}
			}
		}

		fmt.Fprint(&out, s)
	}
	return out.Bytes(), nil
}

// astImports returns the file imports grouped by paragraph.
func astImports(fset *token.FileSet, f *ast.File) [][]*ast.ImportSpec {
	var groups [][]*ast.ImportSpec

	for _, decl := range f.Decls {
		genDecl, ok := decl.(*ast.GenDecl)
		if !ok || genDecl.Tok != token.IMPORT {
			break
		}

		group := []*ast.ImportSpec{}

		var lastLine int
		for _, spec := range genDecl.Specs {
			importSpec := spec.(*ast.ImportSpec)
			pos := importSpec.Path.ValuePos
			line := fset.Position(pos).Line
			if lastLine > 0 && pos > 0 && line-lastLine > 1 {
				groups = append(groups, group)
				group = []*ast.ImportSpec{}
			}
			group = append(group, importSpec)
			lastLine = line
		}
		groups = append(groups, group)
	}

	return groups
}
