	for _, fence := range []string{"```go", "```"} {
		start := strings.Index(code, fence)
		if start < 0 {
			continue
		}
		rest := code[start+len(fence):]
		if end := strings.LastIndex(rest, "```"); end >= 0 {
			rest = rest[:end]
		}
		return strings.TrimSpace(rest)
	}
	return code
}

func parseGoTestCases(response string) ([]TestCase, error) {
	code := extractCode(response)
	if strings.HasSuffix(code, "}") {
		code += ","
	}
	src := wrapperPrefix + code + wrapperSuffix
	fset := token.NewFileSet()
	f, err := parser.ParseFile(fset, "test.go", src, 0)
	if err != nil {
		return nil, fmt.Errorf("parse Go code: %w", err)
	}
	var cases []TestCase
	found := false
	ast.Inspect(f, func(n ast.Node) bool {
		if found {
			return false
		}
		cl, ok := n.(*ast.CompositeLit)
		if !ok {
			return true
		}
		if _, ok := cl.Type.(*ast.ArrayType); !ok {
			return true
		}
		found = true
		for _, elt := range cl.Elts {
			if tc, ok := parseTestCase(elt); ok {
				cases = append(cases, tc)
			}
		}
		return false
	})
	if len(cases) == 0 {
		return nil, errors.New("no test cases found in response")
	}
	return cases, nil
}

func parseTestCase(e ast.Expr) (TestCase, bool) {
	tc := TestCase{
		Args: map[string]string{},
		Want: map[string]string{},
	}
	cl, ok := e.(*ast.CompositeLit)
	if !ok {
		return tc, false
	}
	for _, elt := range cl.Elts {
		kv, ok := elt.(*ast.KeyValueExpr)
		if !ok {
			continue
		}
		key, ok := kv.Key.(*ast.Ident)
		if !ok {
			continue
		}
		switch {
		case key.Name == "name":
			if lit, ok := kv.Value.(*ast.BasicLit); ok && lit.Kind == token.STRING {
				if s, err := strconv.Unquote(lit.Value); err == nil {
					tc.Name = s
				}
			}
		case key.Name == "args":
			if args, ok := kv.Value.(*ast.CompositeLit); ok {
				for _, a := range args.Elts {
					akv, ok := a.(*ast.KeyValueExpr)
					if !ok {
						continue
					}
					ak, ok := akv.Key.(*ast.Ident)
					if !ok || ak.Name == "_" {
						continue
					}
					tc.Args[ak.Name] = exprToString(akv.Value)
				}
			}
		case key.Name == "wantErr":
			if id, ok := kv.Value.(*ast.Ident); ok && id.Name == "true" {
				tc.WantErr = true
			}
		case strings.HasPrefix(key.Name, "want"):
			tc.Want[key.Name] = exprToString(kv.Value)
		}
	}
	if tc.Name == "" {
		return tc, false
	}
	return tc, true
}

func exprToString(e ast.Expr) string {
	switch v := e.(type) {
	case *ast.BasicLit:
		return v.Value
	case *ast.Ident:
		return v.Name
	case *ast.CompositeLit:
		var buf bytes.Buffer
		if err := printer.Fprint(&buf, token.NewFileSet(), v); err != nil {
			return "nil"
		}
		return buf.String()
	case *ast.UnaryExpr:
		return v.Op.String() + exprToString(v.X)
	case *ast.BinaryExpr:
		return exprToString(v.X) + " " + v.Op.String() + " " + exprToString(v.Y)
	default:
		return "nil"
	}
}
