// Package ai generates test cases using a large language model served by
// Ollama.
package ai

import (
	"bytes"
	"encoding/json"
	"errors"
	"fmt"
	"io"
	"net/http"
	"net/url"
	"strings"
	"time"

	"github.com/gotests-reimpl/gotests/internal/models"
)

// maxAttempts is the number of times generation is attempted before giving up.
const maxAttempts = 3

// TestCase is a test case generated by the AI provider.
type TestCase struct {
	Name        string
	Description string
	Args        map[string]string
	Want        map[string]string
	WantErr     bool
}

// Config configures an AI provider.
type Config struct {
	Model    string
	Endpoint string
	MinCases int
	MaxCases int
}

// OllamaProvider generates test cases with Ollama.
type OllamaProvider struct {
	baseURL  string
	model    string
	minCases int
	maxCases int
	client   *http.Client
}

// NewOllamaProvider validates the configuration and creates a provider.
func NewOllamaProvider(cfg Config) (*OllamaProvider, error) {
	if err := validateEndpoint(cfg.Endpoint); err != nil {
		return nil, fmt.Errorf("invalid endpoint: %w", err)
	}
	return &OllamaProvider{
		baseURL:  strings.TrimSuffix(cfg.Endpoint, "/"),
		model:    cfg.Model,
		minCases: cfg.MinCases,
		maxCases: cfg.MaxCases,
		client:   &http.Client{Timeout: 5 * time.Minute},
	}, nil
}

func validateEndpoint(endpoint string) error {
	if endpoint == "" {
		return errors.New("endpoint cannot be empty")
	}
	u, err := url.Parse(endpoint)
	if err != nil {
		return fmt.Errorf("invalid URL format: %w", err)
	}
	if u.Scheme != "http" && u.Scheme != "https" {
		return fmt.Errorf("invalid URL scheme %q: only http and https are allowed", u.Scheme)
	}
	if u.Host == "" {
		return errors.New("URL must include a host")
	}
	return nil
}

// Name returns the provider name.
func (p *OllamaProvider) Name() string { return "ollama" }

// IsAvailable reports whether the Ollama server is reachable.
func (p *OllamaProvider) IsAvailable() bool {
	client := &http.Client{Timeout: 5 * time.Second}
	resp, err := client.Get(p.baseURL + "/api/tags")
	if err != nil {
		return false
	}
	defer resp.Body.Close()
	io.Copy(io.Discard, resp.Body)
	return resp.StatusCode == http.StatusOK
}

// GenerateTestCases generates test cases for the function.
func (p *OllamaProvider) GenerateTestCases(fun *models.Function) ([]TestCase, error) {
	var lastErr error
	for attempt := 0; attempt < maxAttempts; attempt++ {
		prompt := buildPrompt(fun, p.minCases, p.maxCases, lastErr)
		response, err := p.generate(prompt)
		if err != nil {
			lastErr = err
			continue
		}
		cases, err := parseGoTestCases(response)
		if err != nil {
			lastErr = fmt.Errorf("parse Go test cases: %w\n\nLLM Response:\n%s", err, response)
			continue
		}
		if p.maxCases > 0 && len(cases) > p.maxCases {
			cases = cases[:p.maxCases]
		}
		if err := validateCases(cases, fun); err != nil {
			lastErr = err
			continue
		}
		return cases, nil
	}
	return nil, fmt.Errorf("failed after %d attempts: %w", maxAttempts, lastErr)
}

func (p *OllamaProvider) generate(prompt string) (string, error) {
	body, err := json.Marshal(map[string]interface{}{
		"model":  p.model,
		"prompt": prompt,
		"stream": false,
		"options": map[string]interface{}{
			"temperature": 0,
			"seed":        42,
		},
	})
	if err != nil {
		return "", fmt.Errorf("marshal request: %w", err)
	}
	req, err := http.NewRequest(http.MethodPost, p.baseURL+"/api/generate", bytes.NewReader(body))
	if err != nil {
		return "", fmt.Errorf("create request: %w", err)
	}
	req.Header.Set("Content-Type", "application/json")
	resp, err := p.client.Do(req)
	if err != nil {
		return "", fmt.Errorf("http request: %w", err)
	}
	defer resp.Body.Close()
	if resp.StatusCode != http.StatusOK {
		b, _ := io.ReadAll(resp.Body)
		return "", fmt.Errorf("ollama returned %d: %s", resp.StatusCode, string(b))
	}
	var result struct {
		Response string `json:"response"`
	}
	if err := json.NewDecoder(resp.Body).Decode(&result); err != nil {
		return "", fmt.Errorf("decode response: %w", err)
	}
	return result.Response, nil
}

func validateCases(cases []TestCase, fun *models.Function) error {
	if len(cases) > 1 {
		first := caseSignature(cases[0])
		allSame := true
		for _, c := range cases[1:] {
			if caseSignature(c) != first {
				allSame = false
				break
			}
		}
		if allSame {
			return errors.New("generated test cases have duplicate values - need more diversity")
		}
	}
	params := fun.TestParameters()
	results := fun.TestResults()
	for _, c := range cases {
		for _, p := range params {
			if _, ok := c.Args[p.Name]; !ok {
				return fmt.Errorf("test case %q missing argument: %s", c.Name, p.Name)
			}
		}
		if len(c.Want) != len(results) {
			return fmt.Errorf("test case %q has %d return values, expected %d", c.Name, len(c.Want), len(results))
		}
	}
	return nil
}

func caseSignature(c TestCase) string {
	return fmt.Sprintf("%v|%v", c.Args, c.Want)
}
