func buildPrompt(fun *models.Function, minCases, maxCases int, previous error) string {
	scaffold := buildScaffold(fun)
	var b strings.Builder
	b.WriteString("You are a Go testing expert. Generate test cases for the following function.\n\n")
	b.WriteString("Function to test:\n```go\n")
	b.WriteString(functionSource(fun))
	b.WriteString("\n```\n\n")
	b.WriteString("Here is the test scaffold:\n```go\n")
	b.WriteString(scaffold)
	b.WriteString("\n```\n\n")
	fmt.Fprintf(&b, "Generate between %d and %d test cases. Each test case must have UNIQUE, DIFFERENT input values.\n", minCases, maxCases)
	if fun.ReturnsError {
		b.WriteString("Include: 1 valid case, 1 edge case, 1 error case.\n\n")
	} else {
		b.WriteString("Include: valid inputs, edge cases (zero/empty/nil), boundary values.\n\n")
	}
	b.WriteString("Example format:\n```go\n")
	b.WriteString(buildExample(fun))
	b.WriteString("\n```\n\n")
	b.WriteString("Requirements:\n")
	b.WriteString("- DIFFERENT values in each test case (NO duplicates)\n")
	b.WriteString("- Use NAMED fields (e.g., field: value)\n")
	b.WriteString("- Use exact field names from scaffold\n")
	b.WriteString("- Use natural language test names with spaces (e.g., \"valid input\", not \"valid_input\")\n")
	b.WriteString("- Valid Go syntax, realistic values\n")
	if fun.ReturnsError {
		b.WriteString("- Set wantErr based on expected error\n")
	}
	b.WriteString("\nOutput ONLY the test case array, no explanations:\n")
	if previous != nil {
		b.WriteString("PREVIOUS ATTEMPT FAILED:\n")
		b.WriteString(previous.Error())
		b.WriteString("\n\nPlease fix the above issue.\n\n")
	}
	b.WriteString("Now fill in the scaffold above by replacing '// TODO: Add test cases.' with your test cases:\n```go\n")
	b.WriteString(scaffold)
	b.WriteString("\n```\n")
	return b.String()
}

// functionSource reconstructs the source of the function under test.
func functionSource(fun *models.Function) string {
	var b strings.Builder
	b.WriteString("func ")
	if fun.Receiver != nil {
		fmt.Fprintf(&b, "(%s %s) ", fun.Receiver.Name, fun.Receiver.Type.String())
	}
