	for i, p := range fun.Parameters {
		if i > 0 {
			b.WriteString(", ")
		}
		if p.Name != "" {
			b.WriteString(p.Name)
			b.WriteString(" ")
		}
		b.WriteString(p.Type.String())
	}
	b.WriteString(")")
	var results []string
	for _, r := range fun.Results {
		results = append(results, r.Type.String())
	}
	if fun.ReturnsError {
		results = append(results, "error")
	}
	switch len(results) {
	case 0:
	case 1:
		b.WriteString(" " + results[0])
	default:
		b.WriteString(" (" + strings.Join(results, ", ") + ")")
	}
	if fun.Body != "" {
		b.WriteString(" ")
		b.WriteString(fun.Body)
	}
	return b.String()
}

