// goEnv holds the go command environment relevant to package resolution.
type goEnv struct {
	gomod      string
	gomodcache string
	gopath     string
	goroot     string
	goos       string
	goarch     string
}

func loadGoEnv() (*goEnv, error) {
	goPath, err := exec.LookPath("go")
	if err != nil {
		return nil, fmt.Errorf("err: %v: stderr: %s", fmt.Errorf("go command required, not found: %v", err), "")
	}
	cmd := exec.Command(goPath, "env", "GOMOD", "GOMODCACHE", "GOPATH", "GOROOT", "GOOS", "GOARCH")
	var stdout, stderr bytes.Buffer
	cmd.Stdout = &stdout
	cmd.Stderr = &stderr
	if err := cmd.Run(); err != nil {
		return nil, fmt.Errorf("err: %v: stderr: %s", err, stderr.String())
	}
	lines := strings.Split(strings.TrimRight(stdout.String(), "\n"), "\n")
	for len(lines) < 6 {
		lines = append(lines, "")
	}
	return &goEnv{
		gomod:      strings.TrimSpace(lines[0]),
		gomodcache: strings.TrimSpace(lines[1]),
		gopath:     strings.TrimSpace(lines[2]),
		goroot:     strings.TrimSpace(lines[3]),
		goos:       strings.TrimSpace(lines[4]),
		goarch:     strings.TrimSpace(lines[5]),
	}, nil
}

type extPkg struct {
	importPath string
	dir        string
	name       string
	distance   int
}

var modCacheRegexp = regexp.MustCompile(`(.*)@([^/\\]*)(.*)`)

// findExternalImports searches GOPATH or the module cache for packages
// providing the missing references. It returns the selected imports.
func findExternalImports(filename string, missing references) ([]importInfo, error) {
	env, err := loadGoEnv()
	if err != nil {
		return nil, err
	}
	absFile, _ := filepath.Abs(filename)
	srcDir := filepath.Dir(absFile)

	type root struct {
		path     string
		modCache bool
	}
	var roots []root
	if env.goroot != "" {
		roots = append(roots, root{path: filepath.Join(env.goroot, "src")})
	}
	if env.gomod == "" {
		for _, p := range filepath.SplitList(env.gopath) {
			if p != "" {
				roots = append(roots, root{path: filepath.Join(p, "src")})
			}
		}
	} else if env.gomodcache != "" {
		roots = append(roots, root{path: env.gomodcache, modCache: true})
	}

	ctx := build.Default
	ctx.GOROOT = env.goroot
	ctx.GOPATH = env.gopath
	if env.goos != "" {
		ctx.GOOS = env.goos
	}
	if env.goarch != "" {
		ctx.GOARCH = env.goarch
	}

	found := map[string][]extPkg{}
	for _, r := range roots {
		isGoroot := !r.modCache && env.goroot != "" && r.path == filepath.Join(env.goroot, "src")
		walkRoot(r.path, isGoroot, func(dir string) {
			subdir := ""
			if dir != r.path {
				subdir = dir[len(r.path)+len("/"):]
			}
			importPath := filepath.ToSlash(subdir)
			if strings.HasPrefix(importPath, "vendor/") {
				return
			}
			if r.modCache {
				matches := modCacheRegexp.FindStringSubmatch(subdir)
				if len(matches) == 0 {
					return
				}
				modPath, err := unescapeModulePath(filepath.ToSlash(matches[1]))
				if err != nil {
					return
				}
				importPath = path.Join(modPath, filepath.ToSlash(matches[3]))
			}
			if importPath == "" || importPath == "." {
				return
			}
			if !canUse(absFile, dir) {
				return
			}
			candidate := false
			for ident := range missing {
				if matchesPath(ident, importPath) {
					candidate = true
					break
				}
			}
			if !candidate {
				return
			}
			name, err := packageDirToName(dir)
			if err != nil {
				return
			}
			if _, want := missing[name]; !want {
				return
			}
			found[name] = append(found[name], extPkg{
				importPath: importPath,
				dir:        dir,
				name:       name,
				distance:   distance(srcDir, dir),
			})
		})
	}

	var selected []importInfo
	for name, syms := range missing {
		cands := found[name]
		sort.SliceStable(cands, func(i, j int) bool {
			di, dj := cands[i].distance, cands[j].distance
			if di == -1 {
				return false
			}
			if dj == -1 {
				return true
			}
			if di != dj {
				return di < dj
			}
			vi, vj := cands[i].importPath, cands[j].importPath
			if len(vi) != len(vj) {
				return len(vi) < len(vj)
			}
			return vi < vj
		})
		for _, c := range cands {
			exports := loadExports(&ctx, c.dir)
			all := true
			for s := range syms {
				if !exports[s] {
					all = false
					break
				}
			}
			if all {
				selected = append(selected, importInfo{path: c.importPath})
				break
			}
		}
	}
	return selected, nil
}

// walkRoot walks the directory tree calling fn for directories containing
// Go files.
func walkRoot(rootPath string, isGoroot bool, fn func(dir string)) {
	var walk func(dir string)
	walk = func(dir string) {
		entries, err := os.ReadDir(dir)
		if err != nil {
			return
		}
		hasGo := false
		var subdirs []string
		for _, e := range entries {
			name := e.Name()
			if e.IsDir() {
				if name == "" || name[0] == '.' || name[0] == '_' || name == "testdata" {
					continue
				}
				sub := filepath.Join(dir, name)
				if isGoroot && sub == filepath.Join(rootPath, "vendor") {
					continue
				}
				subdirs = append(subdirs, sub)
				continue
			}
			if strings.HasSuffix(name, ".go") {
				hasGo = true
			}
		}
		if hasGo {
			fn(dir)
		}
		for _, s := range subdirs {
			walk(s)
		}
	}
	walk(rootPath)
}

func distance(basepath, targpath string) int {
	p, err := filepath.Rel(basepath, targpath)
	if err != nil {
		return -1
	}
	if p == "." {
		return 0
	}
	return strings.Count(p, string(filepath.Separator)) + 1
}

// canUse reports whether the package in dir is usable from filename.
func canUse(filename, dir string) bool {
	if !strings.Contains(dir, "vendor") && !strings.Contains(dir, "internal") {
		return true
	}
	dirSlash := filepath.ToSlash(dir)
	if !strings.Contains(dirSlash, "/vendor/") && !strings.Contains(dirSlash, "/internal/") && !strings.HasSuffix(dirSlash, "/internal") {
		return true
	}
	absfile, err := filepath.Abs(filename)
	if err != nil {
		return false
	}
	absdir, err := filepath.Abs(dir)
	if err != nil {
		return false
	}
	rel, err := filepath.Rel(absfile, absdir)
	if err != nil {
		return false
	}
	relSlash := filepath.ToSlash(rel)
	if i := strings.LastIndex(relSlash, "../"); i >= 0 {
		relSlash = relSlash[i+len("../"):]
	}
	return !strings.Contains(relSlash, "/vendor/") && !strings.Contains(relSlash, "/internal/") && !strings.HasSuffix(relSlash, "/internal")
}

// matchesPath reports whether ident may match a potential package name
// referred to by path.
func matchesPath(ident, path string) bool {
	lowerIfASCII := func(b byte) byte {
		if 'A' <= b && b <= 'Z' {
			return b + ('a' - 'A')
		}
		return b
	}
	match := func(start, end int) bool {
		ii := len(ident) - 1
		pi := end - 1
		for ; pi >= start && ii >= 0; pi-- {
			pb := path[pi]
			if pb == '-' || pb == '.' {
				continue
			}
			pb = lowerIfASCII(pb)
			ib := lowerIfASCII(ident[ii])
			if pb != ib {
				return false
			}
			ii--
		}
		return ii < 0 && pi < start
	}
	segmentEnd := len(path)
	subsegmentEnd := len(path)
	nslash := 0
	for i := len(path) - 1; i >= 0; i-- {
		switch b := path[i]; b {
		case '/', '\\':
			if match(i+1, segmentEnd) || match(i+1, subsegmentEnd) {
				return true
			}
			nslash++
			if nslash == 2 {
				return false
			}
			segmentEnd, subsegmentEnd = i, i
		case '-', '.':
			if match(i+1, subsegmentEnd) {
				return true
			}
			subsegmentEnd = i
		}
	}
	return match(0, segmentEnd) || match(0, subsegmentEnd)
}

// packageDirToName returns the package name of the Go package in dir.
func packageDirToName(dir string) (string, error) {
	d, err := os.Open(dir)
	if err != nil {
		return "", err
	}
	names, err := d.Readdirnames(-1)
	d.Close()
	if err != nil {
		return "", err
	}
	sort.Strings(names)
	var lastErr error
	var nfile int
	for _, name := range names {
		if !strings.HasSuffix(name, ".go") || strings.HasSuffix(name, "_test.go") {
			continue
		}
		nfile++
		f, err := parser.ParseFile(token.NewFileSet(), filepath.Join(dir, name), nil, parser.PackageClauseOnly)
		if err != nil {
			lastErr = err
			continue
		}
		pkgName := f.Name.Name
		if pkgName == "documentation" || pkgName == "main" {
			continue
		}
		return pkgName, nil
	}
	if lastErr != nil {
		return "", lastErr
	}
	return "", fmt.Errorf("no importable package found in %d Go files", nfile)
}

// loadExports returns the exported package-level names of the package in dir.
func loadExports(ctx *build.Context, dir string) map[string]bool {
	exports := map[string]bool{}
	all, err := os.ReadDir(dir)
	if err != nil {
		return exports
	}
	fset := token.NewFileSet()
	for _, fi := range all {
		if fi.IsDir() {
			continue
		}
		fileName := fi.Name()
		if !strings.HasSuffix(fileName, ".go") || strings.HasSuffix(fileName, "_test.go") {
			continue
		}
		match, err := ctx.MatchFile(dir, fileName)
		if err != nil || !match {
			continue
		}
		f, err := parser.ParseFile(fset, filepath.Join(dir, fileName), nil, 0)
		if err != nil {
			continue
		}
		if f.Name.Name == "documentation" {
			continue
		}
		for name := range f.Scope.Objects {
			if ast.IsExported(name) {
				exports[name] = true
			}
		}
	}
	return exports
}

// unescapeModulePath undoes the module cache case encoding ("!x" -> "X").
func unescapeModulePath(escaped string) (string, error) {
	var b strings.Builder
	bang := false
	for _, r := range escaped {
		if r >= 'A' && r <= 'Z' {
			return "", errors.New("invalid escaped module path")
		}
		if bang {
			bang = false
			if r < 'a' || r > 'z' {
				return "", errors.New("invalid escaped module path")
			}
			b.WriteRune(r - 'a' + 'A')
			continue
		}
		if r == '!' {
			bang = true
			continue
		}
		b.WriteRune(r)
	}
	if bang {
		return "", errors.New("invalid escaped module path")
	}
	return b.String(), nil
}
