				known[imp.path] = k
			}
			for r := range rights {
				k[r] = true
			}
			order = append(order, imp)
		}
	}
	for _, imp := range order {
		if exports, ok := known[imp.path]; ok {
			info.candidates = append(info.candidates, siblingCandidate{imp: imp, exports: exports})
		}
	}
