func (s *siblingInfo) find(name string, syms map[string]bool) (importInfo, bool) {
	for _, c := range s.candidates {
		if c.imp.ident() != name {
			continue
		}
		all := true
		for sym := range syms {
			if !c.exports[sym] {
				all = false
				break
			}
		}
		if all {
			return c.imp, true
		}
	}
	return importInfo{}, false
}
